 * `//pubsub.googleapis.com/projects/{PROJECT_ID}/topics/{TOPIC_ID}`

=item * C<< $msg->sql_resource() >> / C<< $msg->sql_resource($value) >>

Type: C<String>

The SQL name of the entry. SQL names are case-sensitive.

Examples:

* `pubsub.topic.{PROJECT_ID}.{TOPIC_ID}`
* `pubsub.topic.{PROJECT_ID}.`\``{TOPIC.ID.SEPARATED.WITH.DOTS}`\`
* `bigquery.table.{PROJECT_ID}.{DATASET_ID}.{TABLE_ID}`
* `bigquery.dataset.{PROJECT_ID}.{DATASET_ID}`
* `datacatalog.entry.{PROJECT_ID}.{LOCATION_ID}.{ENTRY_GROUP_ID}.{ENTRY_ID}`

Identifiers (`*_ID`) should comply with the
[Lexical structure in GoogleSQL]
(https://cloud.google.com/bigquery/docs/reference/standard-sql/lexical).

=item * C<< $msg->fully_qualified_name() >> / C<< $msg->fully_qualified_name($value) >>

Type: C<String>

[Fully Qualified Name
(FQN)](https://cloud.google.com//data-catalog/docs/fully-qualified-names)
of the resource.

FQNs take two forms:

* For non-regionalized resources:

  `{SYSTEM}:{PROJECT}.{PATH_TO_RESOURCE_SEPARATED_WITH_DOTS}`

* For regionalized resources:

  `{SYSTEM}:{PROJECT}.{LOCATION_ID}.{PATH_TO_RESOURCE_SEPARATED_WITH_DOTS}`

Example for a DPMS table:

`dataproc_metastore:{PROJECT_ID}.{LOCATION_ID}.{INSTANCE_ID}.{DATABASE_ID}.{TABLE_ID}`

=item * C<< $msg->project() >> / C<< $msg->project($value) >>

Type: C<String>

Project where the lookup should be performed. Required to lookup
entry that is not a part of `DPMS` or `DATAPLEX` `integrated_system`
using its `fully_qualified_name`. Ignored in other cases.

=item * C<< $msg->location() >> / C<< $msg->location($value) >>

Type: C<String>

Location where the lookup should be performed. Required to lookup
entry that is not a part of `DPMS` or `DATAPLEX` `integrated_system`
using its `fully_qualified_name`. Ignored in other cases.

=back

=head2 Google::Cloud::Datacatalog::V1::Datacatalog::Entry

Entry metadata.
A Data Catalog entry represents another resource in Google
Cloud Platform (such as a BigQuery dataset or a Pub/Sub topic) or
outside of it. You can use the `linked_resource` field
in the entry resource to refer to the original resource ID of the source
system.

An entry resource contains resource details, for example, its schema.
Additionally, you can attach flexible metadata to an entry in the form of a
[Tag][google.cloud.datacatalog.v1.Tag].

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->name() >> / C<< $msg->name($value) >>

Type: C<String>

Output only. Identifier. The resource name of an entry in URL format.

Note: The entry itself and its child resources might not be
stored in the location specified in its name.

=item * C<< $msg->linked_resource() >> / C<< $msg->linked_resource($value) >>

Type: C<String>

The resource this metadata entry refers to.

For Google Cloud Platform resources, `linked_resource` is the
[Full Resource Name]
(https://cloud.google.com/apis/design/resource_names#full_resource_name).
For example, the `linked_resource` for a table resource from BigQuery is:

`//bigquery.googleapis.com/projects/{PROJECT_ID}/datasets/{DATASET_ID}/tables/{TABLE_ID}`

Output only when the entry is one of the types in the `EntryType` enum.

For entries with a `user_specified_type`, this field is optional and
defaults to an empty string.

The resource string must contain only letters (a-z, A-Z), numbers (0-9),
underscores (_), periods (.), colons (:), slashes (/), dashes (-),
and hashes (#).
The maximum size is 200 bytes when encoded in UTF-8.

=item * C<< $msg->fully_qualified_name() >> / C<< $msg->fully_qualified_name($value) >>

Type: C<String>

[Fully Qualified Name
(FQN)](https://cloud.google.com//data-catalog/docs/fully-qualified-names)
of the resource. Set automatically for entries representing resources from
synced systems. Settable only during creation, and read-only later. Can
be used for search and lookup of the entries.


=item * C<< $msg->type() >> / C<< $msg->type($value) >>

Type: C<Enum> (L<Google::Cloud::Datacatalog::V1::EntryType>)

The type of the entry.

For details, see [`EntryType`](#entrytype).

=item * C<< $msg->user_specified_type() >> / C<< $msg->user_specified_type($value) >>

Type: C<String>

Custom entry type that doesn't match any of the values allowed for input
and listed in the `EntryType` enum.

When creating an entry, first check the type values in the enum.
If there are no appropriate types for the new entry,
provide a custom value, for example, `my_special_type`.

The `user_specified_type` string has the following limitations:

* Is case insensitive.
* Must begin with a letter or underscore.
* Can only contain letters, numbers, and underscores.
* Must be at least 1 character and at most 64 characters long.

=item * C<< $msg->integrated_system() >> / C<< $msg->integrated_system($value) >>

Type: C<Enum> (L<Google::Cloud::Datacatalog::V1::IntegratedSystem>)

Output only. Indicates the entry's source system that Data Catalog
integrates with, such as BigQuery, Pub/Sub, or Dataproc Metastore.

=item * C<< $msg->user_specified_system() >> / C<< $msg->user_specified_system($value) >>

Type: C<String>

Indicates the entry's source system that Data Catalog doesn't
automatically integrate with.

The `user_specified_system` string has the following limitations:

* Is case insensitive.
* Must begin with a letter or underscore.
* Can only contain letters, numbers, and underscores.
* Must be at least 1 character and at most 64 characters long.

=item * C<< $msg->sql_database_system_spec() >> / C<< $msg->sql_database_system_spec($value) >>

Type: C<Message> (L<Google::Cloud::Datacatalog::V1::Datacatalog::SqlDatabaseSystemSpec>)

Specification that applies to a relational database system. Only settable
when `user_specified_system` is equal to `SQL_DATABASE`

=item * C<< $msg->looker_system_spec() >> / C<< $msg->looker_system_spec($value) >>

Type: C<Message> (L<Google::Cloud::Datacatalog::V1::Datacatalog::LookerSystemSpec>)

Specification that applies to Looker sysstem. Only settable when
`user_specified_system` is equal to `LOOKER`

=item * C<< $msg->cloud_bigtable_system_spec() >> / C<< $msg->cloud_bigtable_system_spec($value) >>

Type: C<Message> (L<Google::Cloud::Datacatalog::V1::Datacatalog::CloudBigtableSystemSpec>)

Specification that applies to Cloud Bigtable system. Only settable when
`integrated_system` is equal to `CLOUD_BIGTABLE`

=item * C<< $msg->gcs_fileset_spec() >> / C<< $msg->gcs_fileset_spec($value) >>

Type: C<Message> (L<Google::Cloud::Datacatalog::V1::GcsFilesetSpec::GcsFilesetSpec>)

Specification that applies to a Cloud Storage fileset. Valid only
for entries with the `FILESET` type.

=item * C<< $msg->bigquery_table_spec() >> / C<< $msg->bigquery_table_spec($value) >>

Type: C<Message> (L<Google::Cloud::Datacatalog::V1::TableSpec::BigQueryTableSpec>)

Output only. Specification that applies to a BigQuery table. Valid only
for entries with the `TABLE` type.

=item * C<< $msg->bigquery_date_sharded_spec() >> / C<< $msg->bigquery_date_sharded_spec($value) >>

Type: C<Message> (L<Google::Cloud::Datacatalog::V1::TableSpec::BigQueryDateShardedSpec>)

Output only. Specification for a group of BigQuery tables with
the `[prefix]YYYYMMDD` name pattern.

For more information, see [Introduction to partitioned tables]
(https://cloud.google.com/bigquery/docs/partitioned-tables#partitioning_versus_sharding).

=item * C<< $msg->database_table_spec() >> / C<< $msg->database_table_spec($value) >>

Type: C<Message> (L<Google::Cloud::Datacatalog::V1::Datacatalog::DatabaseTableSpec>)

Specification that applies to a table resource. Valid only
for entries with the `TABLE` or `EXPLORE` type.

=item * C<< $msg->data_source_connection_spec() >> / C<< $msg->data_source_connection_spec($value) >>

Type: C<Message> (L<Google::Cloud::Datacatalog::V1::Datacatalog::DataSourceConnectionSpec>)

Specification that applies to a data source connection. Valid only
for entries with the `DATA_SOURCE_CONNECTION` type.

=item * C<< $msg->routine_spec() >> / C<< $msg->routine_spec($value) >>

Type: C<Message> (L<Google::Cloud::Datacatalog::V1::Datacatalog::RoutineSpec>)

Specification that applies to a user-defined function or procedure. Valid
only for entries with the `ROUTINE` type.

=item * C<< $msg->dataset_spec() >> / C<< $msg->dataset_spec($value) >>

Type: C<Message> (L<Google::Cloud::Datacatalog::V1::Datacatalog::DatasetSpec>)

Specification that applies to a dataset.

=item * C<< $msg->fileset_spec() >> / C<< $msg->fileset_spec($value) >>

Type: C<Message> (L<Google::Cloud::Datacatalog::V1::Datacatalog::FilesetSpec>)

Specification that applies to a fileset resource. Valid only
for entries with the `FILESET` type.

=item * C<< $msg->service_spec() >> / C<< $msg->service_spec($value) >>

Type: C<Message> (L<Google::Cloud::Datacatalog::V1::Datacatalog::ServiceSpec>)

Specification that applies to a Service resource.

=item * C<< $msg->model_spec() >> / C<< $msg->model_spec($value) >>

Type: C<Message> (L<Google::Cloud::Datacatalog::V1::Datacatalog::ModelSpec>)

Model specification.

=item * C<< $msg->feature_online_store_spec() >> / C<< $msg->feature_online_store_spec($value) >>

Type: C<Message> (L<Google::Cloud::Datacatalog::V1::Datacatalog::FeatureOnlineStoreSpec>)

FeatureonlineStore spec for Vertex AI Feature Store.

=item * C<< $msg->display_name() >> / C<< $msg->display_name($value) >>

Type: C<String>

Display name of an entry.

The maximum size is 500 bytes when encoded in UTF-8.
Default value is an empty string.

=item * C<< $msg->description() >> / C<< $msg->description($value) >>

Type: C<String>

Entry description that can consist of several sentences or paragraphs
that describe entry contents.

The description must not contain Unicode non-characters as well as C0
and C1 control codes except tabs (HT), new lines (LF), carriage returns
(CR), and page breaks (FF).
The maximum size is 2000 bytes when encoded in UTF-8.
Default value is an empty string.

=item * C<< $msg->business_context() >> / C<< $msg->business_context($value) >>

Type: C<Message> (L<Google::Cloud::Datacatalog::V1::Datacatalog::BusinessContext>)

Business Context of the entry. Not supported for BigQuery datasets

=item * C<< $msg->schema() >> / C<< $msg->schema($value) >>

Type: C<Message> (L<Google::Cloud::Datacatalog::V1::Schema::Schema>)

Schema of the entry. An entry might not have any schema attached to it.

=item * C<< $msg->source_system_timestamps() >> / C<< $msg->source_system_timestamps($value) >>

Type: C<Message> (L<Google::Cloud::Datacatalog::V1::Timestamps::SystemTimestamps>)

Timestamps from the underlying resource, not from the Data Catalog
entry.

Output only when the entry has a system listed in the `IntegratedSystem`
enum. For entries with `user_specified_system`, this field is optional
and defaults to an empty timestamp.

=item * C<< $msg->usage_signal() >> / C<< $msg->usage_signal($value) >>

Type: C<Message> (L<Google::Cloud::Datacatalog::V1::Usage::UsageSignal>)

Resource usage statistics.

=item * C<< $msg->labels() >> / C<< $msg->labels($value) >>

Type: C<Message> (L<Google::Cloud::Datacatalog::V1::Datacatalog::Entry::LabelsEntry>)

Cloud labels attached to the entry.

In Data Catalog, you can create and modify labels attached only to custom
entries. Synced entries have unmodifiable labels that come from the source
system.

=item * C<< $msg->data_source() >> / C<< $msg->data_source($value) >>

Type: C<Message> (L<Google::Cloud::Datacatalog::V1::DataSource::DataSource>)

Output only. Physical location of the entry.

=item * C<< $msg->personal_details() >> / C<< $msg->personal_details($value) >>

Type: C<Message> (L<Google::Cloud::Datacatalog::V1::Common::PersonalDetails>)

Output only. Additional information related to the entry. Private to the
current user.

=back

