=head2 Google::Cloud::Datacatalog::V1::Datacatalog::UpdateTagTemplateFieldRequest

Request message for
[UpdateTagTemplateField][google.cloud.datacatalog.v1.DataCatalog.UpdateTagTemplateField].

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->name() >> / C<< $msg->name($value) >>

Type: C<String>

Required. The name of the tag template field.

=item * C<< $msg->tag_template_field() >> / C<< $msg->tag_template_field($value) >>

Type: C<Message> (L<Google::Cloud::Datacatalog::V1::Tags::TagTemplateField>)

Required. The template to update.

=item * C<< $msg->update_mask() >> / C<< $msg->update_mask($value) >>

Type: C<Message> (L<Google::Protobuf::FieldMask::FieldMask>)

Optional. Names of fields whose values to overwrite on an individual field
of a tag template. The following fields are modifiable:

* `display_name`
* `type.enum_type`
* `is_required`

If this parameter is absent or empty, all modifiable fields
are overwritten. If such fields are non-required and omitted in the request
body, their values are emptied with one exception: when updating an enum
type, the provided values are merged with the existing values. Therefore,
enum values can only be added, existing enum values cannot be deleted or
renamed.

Additionally, updating a template field from optional to required is
*not* allowed.

=back

